import fs from'node:fs';const rows=JSON.parse(fs.readFileSync('content/algorithms-l8-before-20261119.json','utf8'));const d=new Map();function add(ids,category,explanation){for(const i of ids){if(d.has(i))throw Error('dup '+i);d.set(i,{category,explanation});}}
add([0,46],'堆疊','Overflow（溢位）是容量已滿，卻還要放入新元素。以固定容量為 3 的堆疊為例，依序 push 10、20、30 後，再 push 40 就無位置可寫，應回報 overflow。\n\nUnderflow 是空堆疊還要取出元素，方向相反。這裡採固定容量陣列模型，不會正常寫出陣列界限，也不保證自動擴展；可擴容的實作必須另有配置與搬移機制。填空填 overflow。');
add([8,48],'堆疊','Underflow（下溢）是堆疊已空，卻仍執行 pop。因為沒有頂端元素可回傳，操作必須依介面規定回報錯誤，而非正常取出資料。\n\n例如依序 push 5、pop 得到 5，此時再 pop 就下溢。Overflow 則是已滿還要加入，不能混用；「沒有反應」也沒有正確表達這個非法操作。填空填 underflow。');
add([9,11,59],'堆疊','堆疊遵循 LIFO：Last In, First Out，後進先出。像把盤子一個個疊上去，最後放上的盤子位於頂端，也最先拿走。\n\n依序 push 10、20、30，連續 pop 會得到 30、20、10。FIFO 是佇列規則，依優先級取出屬優先佇列；隨機存取不是堆疊的抽象操作。陣列可以拿來實作堆疊，但「陣列」本身不強制使用 LIFO。填空填 lifo。');
add([12],'堆疊','本題採用從 1 開始存放元素的堆疊模型：top 表示目前元素數／頂端索引，空時設為 0。第一次 push 先把 top 加到 1，再寫入 stack[1]。\n\n如果改用從 0 開始、top 指向最後一個已使用位置的模型，空時常設為 −1；鏈結實作也可能用 NULL 表示空。它們都是不同約定，不能跨模型混用。此題選 0，要和本單元「先增加 top 再寫入」的偽碼一起理解。');
add([19,55],'堆疊','刪除並取出堆疊頂端元素的操作叫 pop；加入頂端叫 push。佇列則使用 enqueue 加入、dequeue 移除。\n\n例如堆疊由底至頂是 4、7、9，pop 回傳 9，剩下 4、7。要先確認堆疊非空，再更新 top，避免 underflow。Pop 不需要搜尋整個堆疊，也不是刪除任意位置的元素。填空填 pop。');
add([27],'堆疊','陣列堆疊需保存陣列內容、最大容量與 top。陣列保存元素，top 指出頂端／目前使用量，容量用來檢查是否還有空間。\n\n例如容量 5、top = 2，表示本模型用了前兩格，下一次 push 寫第 3 格；top = 5 就不能繼續放入。陣列元素已能透過索引定位，不需要每個元素再保存 next／prev 指標；那是鏈結節點的組織方式。');
add([28],'堆疊','Push 加入頂端元素，pop 取出頂端元素，stack-empty 檢查是否為空，都是堆疊的基本介面。\n\n例如先以 stack-empty 確認狀態，再決定能否 pop。Search 雖然可以另外掃描底層陣列或鏈結節點來實作，但不是 LIFO 堆疊規定的基本操作；不能因此把「可以寫出來」與「標準基本介面」視為相同。');
add([30],'堆疊','固定容量陣列的 push 要先檢查 overflow，再增加 top，最後把新值放入 stack[top]。\n\n例如原 top = 2、加入 8，先確認仍有容量，再令 top = 3，寫 stack[3] = 8。Underflow 是 pop 前檢查的空堆疊問題，不能拿來判斷是否還能加入。順序也不能顛倒，否則可能覆寫原頂端或使用錯誤索引。');
add([45],'堆疊','第一空填 S[top[S]]；第二空填 S[top[S]+1]。依題目逐行追蹤 top 的變化，不能只記 pop 一定回傳哪個寫法。\n\nPush：原 top = 2，第一行變成 3，因此第二行要寫 S[3]，即 S[top[S]]。\n\nPop：若原 top = 3 且 S[3] = 9，第三行已先把 top 減成 2，所以回傳原頂端時要讀 S[2+1]，即 S[top[S]+1]。若寫 S[top[S]] 就會誤讀下一層。空堆疊先回報 underflow，不進入這段更新。');
add([4,16,52],'佇列','佇列遵循 FIFO：First In, First Out，先進先出，像排隊買票，先排進來的人先服務。\n\n依序 enqueue 10、20、30，連續 dequeue 得到 10、20、30。堆疊採 LIFO，優先佇列按優先權；二元樹或陣列本身都沒有強制 FIFO 的取出規則，但可用陣列實作佇列。填空填 fifo。');
add([7],'佇列','Head 通常標示佇列前端，也就是下一個要被 dequeue 移除的元素。Tail 則標示加入端；精確是否指向下一個空格，須看實作約定。\n\n例如依序加入 6、8、9，head 指向 6，先移除 6 再前進到 8。最後加入的 9 不是下一個服務對象，中間位置也不是 FIFO 的移除端；只有某些鏈結空佇列的 head 才會是 NULL。');
add([17,58],'佇列','加入佇列的操作是 enqueue，通常從尾端加入；dequeue 則從前端移除。Push／pop 是堆疊用語。\n\n例如目前前到後是 2、5，enqueue 7 後變成 2、5、7，head 仍指向 2。若使用環狀陣列，寫入尾端後還要讓 tail 依容量循環前進；加入前須確認不是滿佇列。填空填 enqueue。');
add([51],'佇列','填 dequeue，表示從佇列前端移除並取得最早加入的元素。\n\n例如前到後為 3、6、8，dequeue 回傳 3，剩 6、8，並更新 head。Enqueue 是尾端加入，pop 是堆疊頂端取出，兩者名稱與抽象行為不同。空佇列不能正常取出元素，必須檢查空狀態並依介面回報。');
add([31],'佇列','佇列基本介面包含 enqueue、dequeue 與 is-empty，分別負責尾端加入、前端移除，以及檢查有沒有元素。\n\n例如 is-empty 為真時，不應直接 dequeue；加入一個元素後才可移除。Search 可以當成額外功能實作，但不是維持 FIFO 必要的基本操作。判斷選項時看它是否直接支援佇列的加入、取出與狀態檢查。');
add([2],'鏈結串列基礎','鏈結串列的插入與刪除可透過修改鄰接連結完成，不必像一般陣列在中間插入時搬移後續所有元素，因此結構調整較有彈性。\n\n例如已知相鄰節點 a、b，要在中間加入 x，只需令 a.next = x、x.next = b。前提是已找到操作位置；搜尋位置仍可能花 O(n)。串列不要求連續記憶體，但需要儲存連結；隨機取得第 i 個元素通常較慢，不能像陣列直接用索引定位。');
add([6,35,49],'鏈結串列基礎','節點通常同時包含資料與連結：key 保存鍵值，next 指向後繼節點；雙向串列另外有 prev 指向前驅。\n\n例如節點的 key = 12、next 指向下一個節點，才能既保留資料又把節點接成清單。只有鍵值無法知道下一個在哪，只有指標則沒有保存此節點的鍵值。Length 通常是整張清單的管理資訊，不是每個節點的必要欄位。填空的關鍵字域填 key；prev 選項以本單元雙向節點模型理解。');
add([13],'鏈結串列基礎','在沒有哨兵節點的普通鏈結串列中，head 指向第一個資料節點；head = NULL 表示連第一個節點都不存在，所以清單為空。\n\n只有一個節點時，head 仍須指向它；是否已滿和配置資源有關，不能從 NULL 推得；環狀串列也會有可指向的節點。若實作採固定哨兵，空表可能是 head 指向哨兵，需先確認使用哪一種模型。');
add([14,18,40],'雙向鏈結串列','雙向串列的每個節點通常有兩個連結：next 指向後繼，prev 指向前驅，因此可以向前或向後走。\n\n例如 a ↔ b ↔ c，從 b 用 next 到 c，用 prev 到 a。單向串列只有 next，若想回到前驅通常須從頭搜尋。這裡的兩個指標只計鄰接連結，不計節點額外的資料欄位；填空與 prev 配對的是 next。');
add([15],'鏈結串列操作','本題保留 O(1)，但需有足夠的刪除位置資訊。在單向串列中，若已知前驅 p 與待刪節點 x，可令 p.next = x.next，用固定次數的連結更新跳過 x。\n\n若只有 x 的指標而不知道前驅，通常還要從 head 尋找前驅，最壞為 O(n)；複製後繼資料的技巧也無法直接處理尾節點，且會改變節點身分。因此「已知指標」須理解為已知能完成刪除的相關指標，不能普遍說單知 x 就一定常數時間。');
add([20,34],'雙向鏈結串列','Prev 與 next 讓節點能直接找到前後鄰居，因此已知節點時，在它前方插入或把它接出清單都比較方便，也能反向走訪。代價是每個節點多存一個連結，修改時也要同步更新多個指標，並不節省節點記憶體。\n\n例如 a ↔ x ↔ b，刪 x 要把 a.next 改成 b、b.prev 改成 a。所謂 O(1) 雙向遍歷，只能指移到相鄰一個節點是 O(1)；從頭走完 n 個節點仍是 O(n)，不是整張表常數時間。');
add([21],'鏈結串列操作','Insert 會增加節點並改接連結，delete 會把節點移出並接回前後節點，因此兩者改變清單結構。\n\n例如 a → b 插入 x 後成 a → x → b；刪 x 又回到 a → b。普通 search 只比較鍵值尋找目標，traverse 只沿連結走訪，兩者不會因此改變節點之間的關係。這裡指標準唯讀查找／遍歷，不包含另行設計的自我調整串列。');
add([22],'集合與實作比較','在本題的固定容量陣列與動態鏈結模型中，陣列空間先決定，可用索引快速取得指定位置；指標實作則可逐個配置節點，插入位置已知時只需調整連結。\n\n例如在陣列中間插入要搬移後方元素，串列可把新節點接入。指標本身及節點都占記憶體，不能說不需要空間。陣列也可另外做動態擴容，但那是額外管理機制，不代表普通固定陣列自動增長。');
add([23,42,57],'鏈結串列操作','刪除雙向串列中的 x，要讓前驅與後繼互相連接：next[prev[x]] = next[x]，以及 prev[next[x]] = prev[x]。兩個方向都必須更新。\n\n例如 a ↔ x ↔ b，第一個指定相當於 a.next = b，第二個相當於 b.prev = a。若 x 在表頭，要改 head；若 x 在表尾，後繼為 NIL，不能對 NIL 寫 prev。一般不需搬動其餘節點資料。偽碼兩空依序填 next[prev[x]]／prev[x]；若先呼叫 LIST_SEARCH，查找 O(n) 也要另計。');
add([36,54],'鏈結串列操作','串列可在頭、尾或中間插入，但都需要更新連結。題目的 LIST_INSERT 是雙向串列表頭插入：先令 x.next 指向舊 head，若舊 head 存在，再把它的 prev 指回 x，所以空格填 prev[head[L]]。\n\n例如原 a ↔ b，插 x 後是 x ↔ a ↔ b：x.next = a、a.prev = x，接著 head = x、x.prev = NIL。若原表為空，就略過 a.prev 這步。這裡改的是連結值，並非搬移所有資料；不能說不需要更新指標。');
add([37,43],'鏈結串列操作','普通鏈結串列無法直接用索引跳到任意位置，搜尋時須由 head 依 next 逐個比較，所以是 linear（線性）遍歷，最壞 O(n)，主要隨清單長度增加。\n\n例如有 5 個節點、目標在最後，就要依序比較 5 次。排序可能讓部分查找提早停止，環狀結構影響停止條件，但一般最壞仍可走完整表；指標存取速度影響實際常數，不改變此模型的漸進階。填空填 linear。');
add([38],'鏈結串列操作','刪除雙向串列節點時，先保存需要的前後位置，更新前驅 next 與後繼 prev，並處理頭尾或單一節點的邊界情況，最後才回收不再需要的節點。\n\n例如刪除唯一節點後，head／tail 都應改成空狀態；不能先 free 節點再讀它的 next，否則可能存取已失效記憶體。手動配置模型需 free／delete；垃圾回收語言則由回收器處理。更新後繼 prev 以前提為雙向串列，單向串列沒有該欄位。');
add([10,56],'環狀串列與哨兵','普通環狀鏈結串列的最後一個節點會接回第一個節點 head，形成環，而不是以 NULL 作結尾。\n\n例如 a → b → c → a，從 c 再走一步就回 a。因此遍歷要以「再次回到起點」等條件停止，不能一直等 NULL。只有一個節點的環才會指向自己；隨機指向任意節點可能形成錯誤環。有哨兵的環狀模型則可能先回到哨兵，需依其設計區分。填空填 head。');
add([25],'環狀串列與哨兵','環狀串列適合反覆輪流處理的工作：環狀 buffer 可重複使用位置，輪流排程可由一個工作移到下一個，需循環遍歷的系統也可自然接回起點。\n\n例如工作甲、乙、丙輪流服務，丙之後回到甲。只把尾端接回頭端，並沒有記錄最大或最小鍵值；若要找最值仍可能須掃描全部節點，不能因此保證 O(1) 找最值。');
add([26],'鏈結串列基礎','單向、雙向與環狀是鏈結串列常見的組織變體，分別著重連結方向與尾端是否回接起點。雙向與環狀還可以結合成雙向環狀串列。\n\n佇列描述的是 FIFO 的抽象使用規則，可用陣列或鏈結串列實作；它不是依節點連接方式命名的串列變體。判斷時分清楚「底層怎麼接」與「元素怎麼進出」。');
add([3,39,50],'環狀串列與哨兵','Sentinel（哨兵）是額外安排的特殊節點，通常不當成一般資料使用，用來統一頭尾或空表的處理。在帶哨兵的雙向環狀串列中，nil[L] 可代表這個節點。\n\n例如空表時哨兵的 next／prev 都指回自己；插入與刪除便可沿用鄰接更新，減少邊界判斷，使程式較易理解。它不是錯誤紀錄，也不是任意下一張清單的指標；哨兵需額外空間，不是為了省掉那一個節點的記憶體。填空填 sentinel。');
add([33],'環狀串列與哨兵','哨兵可用在鏈結串列以簡化邊界，也可用於雜湊表的鏈結桶，或二元樹中代替缺少的子節點，讓演算法少做部分空指標判斷。\n\n本題選這三種典型場景，但哨兵不是它們專屬：鏈結佇列也能使用 dummy／sentinel 節點，簡化空佇列與頭端移除。因而未選「佇列」不能解讀為佇列禁止使用哨兵；應把這組答案視為列舉的用法，概念上沒有絕對排他性。');
add([5,41,44],'動態配置與垃圾回收','指標實作常在執行期間按需配置節點，例如 C 的 malloc 或 C++ 的 new，取得空間後再設定 key 與連結。教材的 allocate 是「配置一個物件」的抽象操作名稱，未必是某語言真正的函數。\n\n例如要插入新節點時，先配置空間、檢查成功，再接入串列；手動管理時用完還需對應 free／delete。不是所有節點都在編譯時固定配置，也不能假定指標一宣告就自帶可用節點。問函數的空格填 malloc，問抽象配置操作時填 allocate。');
add([1,24,53],'動態配置與垃圾回收','Garbage collection（垃圾回收）負責自動回收程式已不可達、之後無法再透過有效參照取得的物件空間，讓動態物件管理較方便，減少手動釋放錯誤。\n\n例如某串列節點移出後沒有其他參照，回收器可在適當時機回收；仍被集合參照的物件即使邏輯上不再需要，也可能不被回收。因此它能降低部分記憶體洩漏與懸空指標風險，卻不保證完全杜絕洩漏。它不負責清理檔案系統、排序陣列、改變陣列容量或最佳化堆疊存取。填空填 garbage collection。');
add([29,47],'集合與實作比較','動態結構／動態集合可在執行中透過插入、刪除改變元素數量。鏈結串列能按需配置節點；堆疊與佇列也能隨 push／pop、enqueue／dequeue 改變內容，因此本題將它們列為動態結構。\n\n但「元素個數會變」不等於「底層容量無上限」：陣列堆疊仍可能固定容量，鏈結版也受可用記憶體限制。靜態陣列的配置大小固定；若額外做成可擴容容器，是另一種實作。串列填空填 dynamic。');
add([32],'集合與實作比較','Dynamic set 的基本操作可包含 search、insert 與 delete：搜尋鍵值、加入元素、移除元素；查詢本身不必改變集合，但仍屬集合介面的一部分。\n\n例如先 search 找到鍵值 7，再 delete 移除它，或 insert 新鍵值 9。Sort 是重新整理元素順序的演算法，並非每個動態集合都需要提供的基本操作；尤其集合的抽象意義本來就不一定要求某種儲存順序。');
if(d.size!==rows.length)throw Error('missing '+rows.map((q,i)=>i).filter(i=>!d.has(i)));
const content=JSON.parse(fs.readFileSync('assets/algorithms-content-explanations.json','utf8'));const identity=q=>JSON.stringify([String(q.type??''),String(q.stem??q.q??''),q.options??q.opts??[],String(q.answer??q.a??''),q.images??[]]);const records=rows.map((q,i)=>{const r={identity:identity(q),sourceExplanation:q.ex||'',...d.get(i)};const id=q.bookmarkId;const old=content.questions[id]||{};content.questions[id]={...old,versions:[...(old.versions||[]).filter(v=>v.identity!==r.identity),r]};return{id,...r,stem:q.q,answer:q.a,type:q.type};});fs.writeFileSync('assets/algorithms-content-explanations.json',JSON.stringify(content,null,2)+'\n');let html=fs.readFileSync('algorithms.html','utf8');html=html.replace(/(<script id="course-content-explanations"[^>]*>)[\s\S]*?(<\/script>)/,(_,a,b)=>a+JSON.stringify(content).replace(/<\//g,'<\\/')+b);html=html.replace(/assets\/topic-order.js\?v=[^"]+/, 'assets/topic-order.js?v=algorithms-l8-20261119');fs.writeFileSync('algorithms.html',html);const topics=['集合與實作比較','堆疊','佇列','鏈結串列基礎','雙向鏈結串列','鏈結串列操作','環狀串列與哨兵','動態配置與垃圾回收'];fs.writeFileSync('content/algorithms-l8-curation-20261119.json',JSON.stringify({course:'algorithms',unit:'L8',date:'2026-11-19',count:rows.length,topicOrder:topics,typeOrder:['單選題','多選題','填空題'],records},null,2)+'\n');let order=fs.readFileSync('assets/topic-order.js','utf8');order=order.replace("  'algorithms/L7':", "  'algorithms/L8':"+JSON.stringify(topics)+",\n  'algorithms/L7':");order=order.replace("(course==='os'&&['synchronization','L9'].includes(unit)?", "((course==='os'&&['synchronization','L9'].includes(unit)||course==='algorithms'&&unit==='L8')?");fs.writeFileSync('assets/topic-order.js',order);console.log('completed',records.length);
